const themeLink=document.createElement('link');themeLink.rel='stylesheet';themeLink.href='/gov-theme.css';document.head.appendChild(themeLink);const landingLink=document.createElement('link');landingLink.rel='stylesheet';landingLink.href='/landing.css';document.head.appendChild(landingLink);const interactionLink=document.createElement('link');interactionLink.rel='stylesheet';interactionLink.href='/interactions.css';document.head.appendChild(interactionLink);const cameraLink=document.createElement('link');cameraLink.rel='stylesheet';cameraLink.href='/camera.css';document.head.appendChild(cameraLink);const cameraFeedLink=document.createElement('link');cameraFeedLink.rel='stylesheet';cameraFeedLink.href='/camera-feed.css';document.head.appendChild(cameraFeedLink);const mobileCctvLink=document.createElement('link');mobileCctvLink.rel='stylesheet';mobileCctvLink.href='/mobile-cctv.css';document.head.appendChild(mobileCctvLink);const mapsLink=document.createElement('link');mapsLink.rel='stylesheet';mapsLink.href='/maps.css';document.head.appendChild(mapsLink);const mapCss=document.createElement('link');mapCss.rel='stylesheet';mapCss.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';mapCss.integrity='sha256-p4NxAoJBhIINfQ4cWPcXLO8N8uVDC/k3KQ9mM7QdV2w=';mapCss.crossOrigin='';document.head.appendChild(mapCss);
const isNativeApp=Boolean(window.Capacitor?.isNativePlatform?.());
const hostedOrigin='https://saarthi-monitoring.onrender.com';
const apiOrigin=isNativeApp?hostedOrigin:'';
const appPublicOrigin=isNativeApp?hostedOrigin:location.origin;
const state={data:null,view:'overview'}; const $=s=>document.querySelector(s);
const esc=s=>String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const badge=v=>`<span class="badge ${String(v).toLowerCase().replace(' ','-')}">${esc(v)}</span>`;
const showToast=m=>{const el=$('#toast');el.textContent=m;el.classList.remove('hidden');setTimeout(()=>el.classList.add('hidden'),3500)};
const api=(url,options={})=>fetch(`${apiOrigin}${url}`,{...options,headers:{'Content-Type':'application/json',...(options.headers||{}),...(sessionStorage.saarthiToken?{Authorization:`Bearer ${sessionStorage.saarthiToken}`}:{})}});
async function load(){const r=await api('/api/dashboard');if(r.status===401){delete sessionStorage.saarthiToken;showAuth();return}state.data=await r.json();if(new URLSearchParams(location.search).get('cameraRoom'))state.view='cctv';render()}
function overview(){const d=state.data;return `<div class="stats"><div class="card"><div class="stat-label">Active projects</div><div class="stat-value">${d.sites.length}</div><span class="trend">All States & UTs covered</span></div><div class="card"><div class="stat-label">CCTV feeds live</div><div class="stat-value">${d.stats.live}<small style="font-size:13px;color:var(--muted)"> / 128</small></div><span class="trend">90.6% availability</span></div><div class="card"><div class="stat-label">Open inspections</div><div class="stat-value">${d.stats.inspections}</div><span class="trend down">↑ 4 need action</span></div><div class="card"><div class="stat-label">Average compliance</div><div class="stat-value">${d.stats.compliance}%</div><span class="trend">↑ 3.2% vs last month</span></div></div><div class="grid"><div class="card"><div class="card-head"><h2>Nationwide monitoring map</h2><button class="text-btn" data-view-go="projects">View projects →</button></div><div id="india-project-map" class="real-map" aria-label="Map showing project locations across India"></div><div class="map-legend"><span class="map-high">●</span> High risk <span class="map-medium">●</span> Medium risk <span class="map-low">●</span> Low risk</div></div><div class="card"><div class="card-head"><h2>Priority alerts</h2><button class="text-btn" data-view-go="reports">View all</button></div>${d.alerts.slice(0,3).map(a=>`<div class="alert"><span class="alert-icon ${a.severity}">!</span><div><strong>${esc(a.type)}</strong><p>${esc(a.site)} · ${esc(a.text)}</p></div><time>${a.time}</time></div>`).join('')}</div></div><div class="card section"><div class="card-head"><h2>Inspection queue</h2><button class="text-btn" data-view-go="inspections">Manage inspections →</button></div>${inspectionTable(d.inspections.slice(0,3))}</div>`}
function inspectionTable(items){return `<table class="table"><thead><tr><th>INSPECTION</th><th>ASSIGNED TO</th><th>WHEN</th><th>PRIORITY</th><th>STATUS</th></tr></thead><tbody>${items.map(i=>`<tr><td><strong>${esc(i.site)}</strong><br><small style="color:var(--muted)">${i.id}</small></td><td>${esc(i.inspector)}</td><td>${esc(i.due)}</td><td>${badge(i.priority)}</td><td>${badge(i.status)}</td></tr>`).join('')}</tbody></table>`}
function projects(){const d=state.data;const states=[...new Set(d.sites.map(s=>s.state))].sort(),available=d.sites.filter(s=>!s.inspectionAssigned);return `<div class="project-toolbar"><div><span class="state-label">STATE / UT</span><select id="state-filter" class="state-filter"><option value="">All States & UTs</option>${states.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select></div><div id="state-summary" class="state-summary">${available.length} projects available for inspection</div></div><input class="filter" id="search" placeholder="Search within selected state by project, district, or scheme…"><div class="project-grid" id="projects-grid">${projectCards(available)}</div>`}
function projectCards(sites){return sites.map(s=>`<article class="card project-card"><div class="card-head"><span>${badge(s.risk)}</span>${badge(s.camera)}</div><h3>${esc(s.name)}</h3><div class="meta">${esc(s.scheme)} · ${esc(s.district)}, ${esc(s.state)}</div><div class="project-row"><span>Compliance score</span><b>${s.score}%</b></div><div class="progress" style="margin:8px 0 16px"><i style="width:${s.score}%"></i></div><div class="project-row"><small style="color:var(--muted)">Attendance: ${s.attendance}%</small><span class="project-action-note">Schedule from Inspections</span></div></article>`).join('')}
function inspections(){return `<div class="card"><div class="card-head"><div><h2>Inspections</h2><p style="margin:5px 0 0;color:var(--muted);font-size:12px">Create an inspection after reviewing the project details, then choose fair auto-assignment or select a specific inspector.</p></div><button class="primary" id="new-inspection">+ New inspection</button></div><div class="assignment-explainer"><b>Assignment options:</b> Auto-assign uses risk, State coverage, workload and a random tie-break. Specific assign lets an authorised official choose the inspector directly.</div>${inspectionTable(state.data.inspections)}</div>`}
function cctv(){const live=state.data.sites.filter(s=>s.camera==='Live').slice(0,2);return `<div class="card"><div class="card-head"><div><h2>Authorized live CCTV feeds</h2><p style="margin:5px 0 0;color:var(--muted);font-size:12px">Connect up to four field phones as temporary mobile CCTV cameras during inspections.</p></div><span class="badge live">● AI SCREENING ACTIVE</span></div><div class="ai-monitor-note"><b>AI-assisted monitoring:</b> screens each connected feed for camera health and unusual movement patterns. <span>Demo safeguard: movement alerts require human review.</span></div><div class="cctv-grid mobile-cctv-grid">${[1,2,3,4].map(slot=>`<div class="feed mobile-cctv" id="mobile-cctv-card-${slot}"><video id="mobile-cctv-video-${slot}" autoplay playsinline></video><span class="status">● MOBILE CCTV ${slot}</span><span class="cam-time" data-clock></span><button class="connect-mobile-camera" data-mobile-slot="${slot}">Connect phone camera</button><div class="cctv-ai-status" id="cctv-ai-status-${slot}">AI: Awaiting camera connection</div><h3>Field camera ${slot}</h3><small id="mobile-cctv-caption-${slot}">Ready for authorized device</small></div>`).join('')}<div class="feed demo" id="camera-feed"><video id="local-camera" autoplay muted playsinline></video><span class="scan"></span><span class="status">● LIVE TEST CAMERA</span><span class="cam-time" data-clock></span><button class="camera-start" id="start-camera">Start live camera</button><button class="hidden" id="stop-camera">Stop</button><h3>Secure test feed</h3><small>DEVICE CAM · LOCAL</small></div>${live.map((s,n)=>`<div class="feed demo"><span class="scan"></span><span class="status">● LIVE</span><span class="cam-time" data-clock></span><button data-vc="${esc(s.name)}">Start VC</button><h3>${esc(s.name)}</h3><small>CAM 0${n+1} · 1080p</small></div>`).join('')}</div></div>`}
function reports(){const r=state.data.reports;return `<div class="card"><div class="card-head"><div><h2>Inspection reports</h2><p style="margin:5px 0 0;color:var(--muted);font-size:12px">All reports include capture time, location and evidence integrity metadata.</p></div><button class="primary" id="report-top">+ New report</button></div>${r.length?`<table class="table"><thead><tr><th>REPORT</th><th>PROJECT</th><th>FINDING</th><th>STATUS</th></tr></thead><tbody>${r.map(x=>`<tr><td><strong>${x.id}</strong><br><small style="color:var(--muted)">${new Date(x.submittedAt).toLocaleString()}</small></td><td>${esc(x.site)}</td><td>${esc(x.finding)}</td><td>${badge(x.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No submitted reports yet. Start a mobile inspection to create a geo-tagged report.</div>'}</div>`}
function render(){if(window.nationwideMap){window.nationwideMap.remove();window.nationwideMap=null}const titles={overview:'Good morning, Arjun',projects:'Project monitoring',inspections:'Inspections',cctv:'Live CCTV monitoring',reports:'Inspection reports'};$('#page-title').textContent=titles[state.view];$('#content').innerHTML=({overview,projects,inspections,cctv,reports})[state.view]();document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===state.view));bind();if(state.view==='overview')initIndiaMap()}
function reportModal(){return `<h2>Submit inspection report</h2><p>Capture verified field evidence and use device GPS to stamp the actual inspection location.</p><form id="report-form"><div class="form-grid"><label class="field full">Project<select name="site" required>${state.data.sites.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></label><label class="field">Inspection outcome<select name="finding"><option>Compliant</option><option>Needs corrective action</option><option>Critical non-compliance</option></select></label><label class="field">Evidence type<select name="evidence"><option>Photo + geo-tag</option><option>Video evidence</option><option>VC verification</option></select></label><label class="field full">Inspection notes<textarea name="notes" placeholder="Enter verified observations and required corrective action…" required></textarea></label><div class="field full geo-field"><div class="geo-heading"><span>Geo-tagged inspection location</span><button class="text-btn" type="button" id="expand-geo-map">Expand map ↗</button></div><div id="inspection-geo-map" class="inspection-map"><div class="geo-loading">Loading secure map…</div></div><div class="geo-actions"><button class="secondary geo-button" type="button" id="get-current-location">⌖ Capture precise GPS</button><button class="secondary" type="button" id="center-geo-pin" disabled>◎ Center location</button></div><div class="geo-details" id="geo-details"><span class="geo-dot"></span><span>GPS location not captured yet</span></div><input name="location" id="inspection-location" value="GPS location not captured yet" readonly></div></div><div class="form-actions"><button type="button" class="secondary" id="close-form">Cancel</button><button class="primary">Submit verified report</button></div></form>`}
function inspectionModal(){const available=state.data.sites.filter(site=>!site.inspectionAssigned),inspectors=state.data.inspectors||[];return `<h2>New inspection</h2><p>Add the inspection details, then choose how the responsible inspector should be assigned.</p><form id="inspection-assign-form"><div class="form-grid"><label class="field full">Project<select name="siteId" required>${available.map(site=>`<option value="${esc(site.id)}">${esc(site.name)} · ${esc(site.district)}, ${esc(site.state)}</option>`).join('')}</select></label><label class="field">Due by<select name="due"><option>Within 24 hours</option><option>Within 48 hours</option><option>Within 7 days</option><option>Scheduled follow-up</option></select></label><label class="field">Priority<select name="priority"><option>High</option><option>Medium</option><option>Low</option></select></label><label class="field full">Inspection purpose / instructions<textarea name="notes" placeholder="For example: Verify attendance records and CCTV availability." required></textarea></label><label class="field full">Specific inspector <small>(only used for Specific assign)</small><select name="inspectorName"><option value="">Select inspector</option>${inspectors.map(inspector=>`<option value="${esc(inspector.name)}">${esc(inspector.name)} · ${esc(inspector.role)} · workload ${inspector.workload}</option>`).join('')}</select></label></div><div class="assignment-choice"><b>Choose assignment method</b><span>Auto-assignment is fair by design; specific assignment is recorded in the audit trail.</span></div><div class="form-actions"><button type="button" class="secondary" id="close-form">Cancel</button><button class="secondary assignment-button" type="submit" value="specific">Assign to selected inspector</button><button class="primary" type="submit" value="auto">✦ Auto-assign fairly</button></div></form>`}
function notificationsModal(){return `<h2>Notifications</h2><p>Latest system alerts and inspection activity.</p><div class="notification-list">${state.data.alerts.map(a=>`<div class="alert"><span class="alert-icon ${a.severity}">!</span><div><strong>${esc(a.type)}</strong><p>${esc(a.site)} · ${esc(a.text)}</p></div><time>${esc(a.time)}</time></div>`).join('')||'<div class="empty">You have no new notifications.</div>'}</div>`}
function toggleProfileMenu(){let menu=$('#profile-menu');if(menu){menu.remove();return}menu=document.createElement('div');menu.id='profile-menu';menu.innerHTML=`<div class="profile-menu-head"><span class="avatar">AM</span><div><b>Arjun Mehta</b><small>PMU Inspector · GOV-2026-1001</small></div></div><button data-profile-action="account">◉ My profile</button><button data-profile-action="settings">⚙ Account settings</button><hr><button data-profile-action="logout" class="logout-action">↪ Log out</button>`;document.body.appendChild(menu);menu.querySelector('[data-profile-action="account"]').onclick=()=>{menu.remove();showToast('Profile details are verified through your Government Employee ID.')};menu.querySelector('[data-profile-action="settings"]').onclick=()=>{menu.remove();showToast('Account settings will be managed through the official identity service.')};menu.querySelector('[data-profile-action="logout"]').onclick=logout}
async function logout(){try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}delete sessionStorage.saarthiToken;$('#profile-menu')?.remove();showLanding();showToast('You have been logged out securely.')}
function vcModal(site){return `<h2>Initiate surprise VC</h2><p>A secure verification request will be sent immediately and retained in the audit trail.</p><form id="vc-form"><div class="form-grid"><label class="field full">Project<select name="site">${state.data.sites.map(s=>`<option ${s.name===site?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label class="field full">Contact / role<input name="contact" placeholder="Project Incharge / Staff / Beneficiary" required></label></div><div class="form-actions"><button type="button" class="secondary" id="close-form">Cancel</button><button class="primary">Send VC request</button></div></form>`}
let leafletLoader;
function ensureLeaflet(){if(window.L)return Promise.resolve(window.L);if(leafletLoader)return leafletLoader;leafletLoader=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.integrity='sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=';script.crossOrigin='';script.onload=()=>resolve(window.L);script.onerror=reject;document.head.appendChild(script)});return leafletLoader}
function addMapTiles(map){L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap contributors'}).addTo(map)}
async function initIndiaMap(){const el=$('#india-project-map');if(!el||el.dataset.ready)return;el.dataset.ready='true';try{await ensureLeaflet();const canvasRenderer=L.canvas({padding:.2});const map=L.map(el,{scrollWheelZoom:false,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false,preferCanvas:true,renderer:canvasRenderer}).setView([22.5,79.2],4);window.nationwideMap=map;L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:8,maxNativeZoom:6,updateWhenIdle:true,updateWhenZooming:false,keepBuffer:1,attribution:'© OpenStreetMap contributors'}).addTo(map);const colors={High:'#cf4e3b',Medium:'#d9961d',Low:'#16804d'};const points=[];state.data.sites.filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lng)).forEach(site=>{const marker=L.circleMarker([site.lat,site.lng],{renderer:canvasRenderer,radius:5,color:'#fff',weight:1.5,fillColor:colors[site.risk]||colors.Low,fillOpacity:.95}).addTo(map);marker.bindPopup(`<b>${esc(site.name)}</b><br>${esc(site.district)}, ${esc(site.state)}<br>Risk: ${esc(site.risk)} · Compliance: ${site.score}%`,{maxWidth:230});points.push([site.lat,site.lng])});if(points.length)map.fitBounds(points,{padding:[12,12],maxZoom:5,animate:false});requestAnimationFrame(()=>map.invalidateSize({animate:false}))}catch{el.innerHTML='<div class="map-fallback">Map could not load. Please check your internet connection.</div>'}}
async function initInspectionMap(){const el=$('#inspection-geo-map');if(!el)return;try{await ensureLeaflet();const map=L.map(el,{scrollWheelZoom:true,zoomControl:true}).setView([20.5937,78.9629],4);addMapTiles(map);window.inspectionGeo={map,marker:null,accuracyCircle:null,point:null};const capture=$('#get-current-location'),center=$('#center-geo-pin'),expand=$('#expand-geo-map');const focus=()=>{const geo=window.inspectionGeo;if(!geo?.point)return;geo.map.flyTo(geo.point,Math.max(16,geo.map.getZoom()),{animate:true,duration:.65});geo.marker.openPopup()};center.onclick=focus;expand.onclick=()=>{el.classList.toggle('expanded');expand.textContent=el.classList.contains('expanded')?'Collapse map ↙':'Expand map ↗';setTimeout(()=>{map.invalidateSize({animate:true});focus()},180)};capture.onclick=()=>{if(!navigator.geolocation){showToast('This browser does not support GPS location.');return}capture.disabled=true;capture.textContent='Locating device…';$('#geo-details').innerHTML='<span class="geo-dot locating"></span><span>Acquiring high-accuracy GPS signal…</span>';navigator.geolocation.getCurrentPosition(position=>{const {latitude,longitude,accuracy}=position.coords;const point=[latitude,longitude],capturedAt=new Date(position.timestamp);const geo=window.inspectionGeo;geo.point=point;if(geo.marker)geo.marker.setLatLng(point);else geo.marker=L.marker(point,{title:'Verified inspection location'}).addTo(map);if(geo.accuracyCircle)geo.accuracyCircle.setLatLng(point).setRadius(accuracy);else geo.accuracyCircle=L.circle(point,{radius:accuracy,color:'#1a5ca8',weight:1,fillColor:'#3d83cf',fillOpacity:.14}).addTo(map);geo.marker.bindPopup(`<b>Verified inspection location</b><br>${latitude.toFixed(6)}, ${longitude.toFixed(6)}<br>Accuracy: ±${Math.round(accuracy)} m`).openPopup();map.flyTo(point,16,{animate:true,duration:.75});const locationValue=`${latitude.toFixed(6)}, ${longitude.toFixed(6)} · accuracy ±${Math.round(accuracy)}m · ${capturedAt.toLocaleString()}`;$('#inspection-location').value=locationValue;$('#geo-details').innerHTML=`<span class="geo-dot verified">✓</span><span><b>GPS captured</b> · ${latitude.toFixed(6)}, ${longitude.toFixed(6)} · ±${Math.round(accuracy)} m</span>`;capture.textContent='↻ Refresh precise GPS';capture.disabled=false;center.disabled=false;showToast('Precise GPS location captured and pinned on the map.');},error=>{capture.disabled=false;capture.textContent='⌖ Capture precise GPS';$('#geo-details').innerHTML='<span class="geo-dot error">!</span><span>Location was not captured. Enable device location and try again.</span>';showToast(error.code===1?'Location permission was not granted.':'Could not obtain a precise location. Try again outdoors or enable GPS.')},{enableHighAccuracy:true,timeout:20000,maximumAge:0})}}catch{el.innerHTML='<div class="map-fallback">Map unavailable. GPS coordinates can still be captured.</div>'}}
function openModal(html){$('#modal-content').innerHTML=html;$('#modal').classList.remove('hidden');if($('#inspection-geo-map'))setTimeout(initInspectionMap,0)}function closeModal(){$('#modal').classList.add('hidden')}
function bind(){
  document.querySelectorAll('[data-view-go]').forEach(x=>x.onclick=()=>{state.view=x.dataset.viewGo;render()});
  $('#open-report').onclick=()=>openModal(inspectionModal());
  const notifications=$('.icon-btn'); if(notifications) notifications.onclick=()=>openModal(notificationsModal());
  const profile=$('.profile'); if(profile) profile.onclick=toggleProfileMenu;
  const reportTop=$('#report-top'); if(reportTop) reportTop.onclick=()=>openModal(reportModal());
  const newInspection=$('#new-inspection'); if(newInspection) newInspection.onclick=()=>openModal(inspectionModal());
  const search=$('#search');
  if(search) search.oninput=e=>{ const q=e.target.value.toLowerCase(); $('#projects-grid').innerHTML=projectCards(state.data.sites.filter(s=>Object.values(s).join(' ').toLowerCase().includes(q))); };
  const stateFilter=$('#state-filter');
  if(stateFilter){const applyState=()=>{const chosen=stateFilter.value,q=($('#search').value||'').toLowerCase(),shown=state.data.sites.filter(s=>!s.inspectionAssigned&&(!chosen||s.state===chosen)&&Object.values(s).join(' ').toLowerCase().includes(q));$('#projects-grid').innerHTML=projectCards(shown);$('#state-summary').textContent=chosen?`${shown.length} project${shown.length===1?'':'s'} available in ${chosen}`:`${shown.length} projects available for inspection`;};stateFilter.onchange=applyState;$('#search').oninput=applyState;}
  document.querySelectorAll('[data-vc]').forEach(button=>button.onclick=()=>openModal(vcModal(button.dataset.vc)));
  const startCamera=$('#start-camera'), stopCamera=$('#stop-camera');
  if(startCamera) startCamera.onclick=startLiveCamera;
  if(stopCamera) stopCamera.onclick=stopLiveCamera;
  document.querySelectorAll('[data-mobile-slot]').forEach(button=>button.onclick=()=>createMobileCctvRoom(Number(button.dataset.mobileSlot)));
  document.querySelectorAll('[data-clock]').forEach(clock=>clock.textContent=new Date().toLocaleTimeString('en-IN',{hour12:false}));
}
async function startLiveCamera(){try{const stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:false});const video=$('#local-camera');video.srcObject=stream;$('#camera-feed').classList.add('camera-active');$('#stop-camera').classList.remove('hidden');showToast('Secure live test camera started')}catch(err){showToast('Camera access was not granted. Please allow it in the browser.') }}
function stopLiveCamera(){const video=$('#local-camera');if(video&&video.srcObject){video.srcObject.getTracks().forEach(t=>t.stop());video.srcObject=null}$('#camera-feed').classList.remove('camera-active');$('#stop-camera').classList.add('hidden');showToast('Live test camera stopped')}
const mobileRtcConfig={iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:global.stun.twilio.com:3478'}],iceCandidatePoolSize:2};
async function createMobileCctvRoom(slot){try{const response=await api('/api/mobile-cctv/room',{method:'POST',body:'{}'});if(!response.ok)throw new Error('Room creation failed');const {roomId}=await response.json();const clientId=crypto.randomUUID();const peer=new RTCPeerConnection(mobileRtcConfig);window.mobileCctv=window.mobileCctv||{};window.mobileCctv[slot]={roomId,clientId,peer,phoneId:null,pendingCandidates:[]};peer.onicecandidate=e=>{if(e.candidate)sendMobileCctvSignal(roomId,clientId,{kind:'candidate',candidate:e.candidate},window.mobileCctv[slot].phoneId)};peer.onconnectionstatechange=()=>{const label=$(`#cctv-ai-status-${slot}`);if(peer.connectionState==='failed'||peer.connectionState==='disconnected')label.textContent='Connection interrupted. Reconnect the field phone.'};peer.ontrack=e=>{const video=$(`#mobile-cctv-video-${slot}`);video.srcObject=e.streams[0];video.play().catch(()=>{});$(`#mobile-cctv-caption-${slot}`).textContent='Connected field phone · live';$(`#cctv-ai-status-${slot}`).textContent='AI: Analysing feed health and movement';startCctvAnalysis(slot,video);};await sendMobileCctvSignal(roomId,clientId,{kind:'monitor-ready',monitorId:clientId});window.mobileCctv[slot].poll=setInterval(()=>pollMobileCctvSignals(slot),1000);const link=`${appPublicOrigin}/?mobileCctv=${roomId}&slot=${slot}`;$(`#mobile-cctv-caption-${slot}`).textContent='Open this link on the field phone';const card=$(`#mobile-cctv-card-${slot}`);card.querySelector('.connect-mobile-camera').outerHTML=`<button class="connect-mobile-camera" id="copy-mobile-link-${slot}">Copy phone link</button><div class="mobile-link">${link}</div>`;$(`#copy-mobile-link-${slot}`).onclick=async()=>{try{await navigator.clipboard.writeText(link);showToast(`Mobile CCTV ${slot} link copied.`)}catch{showToast('Copy the displayed link and open it on the field phone.')}};$(`#cctv-ai-status-${slot}`).textContent='AI: Waiting for field phone to allow camera';}catch(e){showToast('Could not create the mobile CCTV room. Please try again.')}}
async function sendMobileCctvSignal(roomId,clientId,signal,target=null){return api('/api/mobile-cctv/signal',{method:'POST',body:JSON.stringify({roomId,clientId,signal,target})})}
async function pollMobileCctvSignals(slot){const current=window.mobileCctv?.[slot];if(!current)return;try{const response=await api(`/api/mobile-cctv/signals?roomId=${encodeURIComponent(current.roomId)}&clientId=${encodeURIComponent(current.clientId)}&t=${Date.now()}`,{cache:'no-store'});if(!response.ok)return;const {signals}=await response.json();for(const message of signals){const signal=message.signal;if(signal.kind==='offer'){current.phoneId=message.from;await current.peer.setRemoteDescription(new RTCSessionDescription(signal.sdp));for(const candidate of current.pendingCandidates.splice(0))await current.peer.addIceCandidate(candidate);const answer=await current.peer.createAnswer();await current.peer.setLocalDescription(answer);await sendMobileCctvSignal(current.roomId,current.clientId,{kind:'answer',sdp:answer},current.phoneId)}else if(signal.kind==='candidate'){const candidate=new RTCIceCandidate(signal.candidate);if(current.peer.remoteDescription)await current.peer.addIceCandidate(candidate);else current.pendingCandidates.push(candidate)}}}catch{}}
function startCctvAnalysis(slot,video){if(window.mobileCctv?.[slot]?.analysis)return;const canvas=document.createElement('canvas');canvas.width=48;canvas.height=36;const context=canvas.getContext('2d',{willReadFrequently:true});let previous=null;window.mobileCctv[slot].analysis=setInterval(()=>{if(video.readyState<2)return;context.drawImage(video,0,0,48,36);const data=context.getImageData(0,0,48,36).data;if(previous){let change=0;for(let i=0;i<data.length;i+=12)change+=Math.abs(data[i]-previous[i]);const average=change/(data.length/12);const label=$(`#cctv-ai-status-${slot}`);if(average>26){label.textContent='AI alert: Unusual movement detected — review required';label.classList.add('ai-alert')}else{label.textContent='AI: Feed stable · movement within normal range';label.classList.remove('ai-alert')}}previous=data},2500)}
function showMobileCctvPhone(roomId,slot){document.querySelector('#public-portal')?.remove();document.querySelector('#auth-gate')?.remove();const panel=document.createElement('div');panel.id='mobile-cctv-phone';panel.innerHTML=`<div class="phone-camera-panel"><span>SAARTHI · AUTHORIZED FIELD DEVICE</span><h1>Mobile CCTV camera ${esc(slot||'')}</h1><p>Allow camera access. Keep this page open while the official dashboard receives your live feed.</p><video id="phone-camera-preview" autoplay muted playsinline></video><button id="start-phone-cctv">Start secure camera</button><p id="phone-camera-status">Ready to connect.</p></div>`;document.body.appendChild(panel);$('#start-phone-cctv').onclick=()=>startPhoneCctv(roomId,slot)}
async function startPhoneCctv(roomId,slot){const button=$('#start-phone-cctv');try{button.disabled=true;button.textContent='Starting camera…';const phoneId=crypto.randomUUID();const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});$('#phone-camera-preview').srcObject=stream;const peer=new RTCPeerConnection(mobileRtcConfig);const pendingCandidates=[];let monitorId=null;const send=(signal,target=null)=>fetch(`/api/mobile-cctv/signal`,{method:'POST',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({roomId,clientId:phoneId,signal,target})});peer.onicecandidate=e=>{if(e.candidate&&monitorId)send({kind:'candidate',candidate:e.candidate},monitorId)};peer.onconnectionstatechange=()=>{if(peer.connectionState==='connected')$('#phone-camera-status').textContent='Live — your phone is now shown in CCTV monitoring.';if(peer.connectionState==='failed'){$('#phone-camera-status').textContent='Connection failed. Return to the dashboard and create a fresh camera link.';button.disabled=false;button.textContent='Try again'}};stream.getTracks().forEach(track=>peer.addTrack(track,stream));$('#phone-camera-status').textContent='Camera started. Waiting for monitoring dashboard…';setInterval(async()=>{try{const response=await fetch(`/api/mobile-cctv/signals?roomId=${encodeURIComponent(roomId)}&clientId=${encodeURIComponent(phoneId)}&t=${Date.now()}`,{cache:'no-store'});if(!response.ok)return;const {signals}=await response.json();for(const message of signals){const signal=message.signal;if(signal.kind==='monitor-ready'&&!monitorId){monitorId=signal.monitorId;const offer=await peer.createOffer();await peer.setLocalDescription(offer);await send({kind:'offer',sdp:offer},monitorId)}else if(signal.kind==='answer'){await peer.setRemoteDescription(new RTCSessionDescription(signal.sdp));for(const candidate of pendingCandidates.splice(0))await peer.addIceCandidate(candidate)}else if(signal.kind==='candidate'){const candidate=new RTCIceCandidate(signal.candidate);if(peer.remoteDescription)await peer.addIceCandidate(candidate);else pendingCandidates.push(candidate)}}}catch{}},800)}catch{button.disabled=false;button.textContent='Start secure camera';$('#phone-camera-status').textContent='Camera permission was not granted. Allow camera access and try again.'}}
async function sendCameraSignal(signal){return api('/api/camera/signal',{method:'POST',body:JSON.stringify({roomId:window.cameraRoom,clientId:window.cameraClientId,signal})})}
async function setupPeer(withCamera){window.cameraClientId=crypto.randomUUID();window.peer=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});window.peer.onicecandidate=e=>{if(e.candidate)sendCameraSignal({kind:'candidate',candidate:e.candidate})};window.peer.ontrack=e=>{const remote=$('#peer-remote');remote.srcObject=e.streams[0];$('#camera-status').textContent='Connected — live teammate camera is visible.'};if(withCamera){window.peerStream=await navigator.mediaDevices.getUserMedia({video:true,audio:false});$('#peer-local').srcObject=window.peerStream;window.peerStream.getTracks().forEach(t=>window.peer.addTrack(t,window.peerStream))}window.cameraPoll=setInterval(pollCameraSignals,1200)}
async function createCameraRoom(){try{const r=await api('/api/camera/room',{method:'POST',body:'{}'});const x=await r.json();window.cameraRoom=x.roomId;await setupPeer(true);const offer=await window.peer.createOffer();await window.peer.setLocalDescription(offer);await sendCameraSignal({kind:'offer',sdp:offer});const link=`${location.origin}${location.pathname}?cameraRoom=${x.roomId}`;$('#camera-invite').classList.remove('hidden');$('#camera-invite').innerHTML=`<b>Room ${x.roomId} created.</b><br><small>Send this link to one verified teammate:</small><input readonly value="${link}"><button id="copy-camera-link">Copy link</button>`;$('#copy-camera-link').onclick=async()=>{await navigator.clipboard.writeText(link);showToast('Secure camera room link copied.')};$('#camera-status').textContent='Camera is live. Waiting for your teammate to join.'}catch(e){showToast('Camera access was not granted. Please allow it in the browser.')}}
async function joinCameraRoom(){const roomId=$('#camera-room-code').value.trim();if(!roomId)return showToast('Enter the teammate camera room code.');try{window.cameraRoom=roomId;await api('/api/camera/room',{method:'POST',body:JSON.stringify({roomId})});await setupPeer(false);$('#camera-status').textContent='Joining camera room — waiting for host connection.'}catch(e){showToast('Could not join this camera room.')}}
async function pollCameraSignals(){if(!window.cameraRoom||!window.peer)return;const r=await api(`/api/camera/signals?roomId=${encodeURIComponent(window.cameraRoom)}&clientId=${encodeURIComponent(window.cameraClientId)}`);if(!r.ok)return;const x=await r.json();for(const item of x.signals){const s=item.signal;if(s.kind==='offer'){await window.peer.setRemoteDescription(new RTCSessionDescription(s.sdp));const answer=await window.peer.createAnswer();await window.peer.setLocalDescription(answer);await sendCameraSignal({kind:'answer',sdp:answer});}else if(s.kind==='answer')await window.peer.setRemoteDescription(new RTCSessionDescription(s.sdp));else if(s.kind==='candidate')await window.peer.addIceCandidate(new RTCIceCandidate(s.candidate));}}
const liveCss=`.feed.demo{min-height:240px;isolation:isolate}.feed.demo:after{content:'';position:absolute;inset:0;z-index:-2;background:radial-gradient(ellipse at 25% 35%,#4c795f 0 6%,transparent 7%),radial-gradient(ellipse at 65% 67%,#759770 0 5%,transparent 6%),linear-gradient(115deg,#0b211c,#1c4a3c 55%,#0e3027);animation:feedShift 7s ease-in-out infinite alternate}.feed video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-1;background:#102a22}.feed.demo .scan{position:absolute;inset:0;background:linear-gradient(transparent 48%,rgba(211,243,106,.16) 50%,transparent 52%);background-size:100% 12px;opacity:.35;pointer-events:none}.feed .cam-time{position:absolute;left:15px;top:45px;font:11px monospace;letter-spacing:.5px}.feed button{position:absolute;right:14px;top:13px;border:1px solid #ffffff66;background:#143c30cc;color:white;border-radius:6px;padding:6px 8px;font-size:11px;font-weight:bold;cursor:pointer}.feed .camera-start{left:50%;top:50%;right:auto;transform:translate(-50%,-50%);background:#d5f36a;color:#0b3d30;border:0;padding:10px 13px;white-space:nowrap}.feed.camera-active .camera-start{display:none}.feed.camera-active:after{display:none}@keyframes feedShift{from{transform:scale(1) translateX(-1%)}to{transform:scale(1.12) translateX(2%)}}`;const liveStyle=document.createElement('style');liveStyle.textContent=liveCss;document.head.appendChild(liveStyle);
async function assign(siteId,details={}){const r=await api('/api/assign',{method:'POST',body:JSON.stringify({siteId,...details})});const x=await r.json();if(!r.ok)return showToast(x.error||'Could not assign this inspection.');await load();showToast(`Inspection assigned to ${x.inspector}: ${x.assignmentBasis}.`)}
$('#close-modal').onclick=closeModal;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};document.addEventListener('click',async e=>{if(e.target.id==='close-form')closeModal();if(e.target.closest('.nav')){state.view=e.target.closest('.nav').dataset.view;render()}if(e.target.closest('#inspection-assign-form')){e.preventDefault();if(e.target.tagName==='BUTTON'&&e.target.type!=='button'){const form=e.target.closest('form'),data=Object.fromEntries(new FormData(form)),method=e.target.value;if(method==='specific'&&!data.inspectorName)return showToast('Select an inspector before using Specific assign.');const button=e.target;button.disabled=true;button.textContent='Assigning…';await assign(data.siteId,{due:data.due,priority:data.priority,notes:data.notes,inspectorName:method==='specific'?data.inspectorName:''});closeModal();state.view='inspections';render()}}if(e.target.closest('#report-form')){e.preventDefault();if(e.target.tagName==='BUTTON'&&e.target.type!=='button'){const f=new FormData(e.target.closest('form'));const data=Object.fromEntries(f);if(String(data.location||'').startsWith('GPS location'))return showToast('Capture the current GPS location before submitting the report.');await api('/api/reports',{method:'POST',body:JSON.stringify(data)});closeModal();state.view='reports';await load();showToast('Verified inspection report submitted')}}if(e.target.closest('#vc-form')){e.preventDefault();if(e.target.tagName==='BUTTON'&&e.target.type!=='button'){const data=Object.fromEntries(new FormData(e.target.closest('form')));await api('/api/vc',{method:'POST',body:JSON.stringify(data)});closeModal();await load();showToast('Secure VC verification request sent')}}});
function showAuth(){
  document.querySelector('#public-portal')?.remove();
  let gate=document.querySelector('#auth-gate'); if(!gate){gate=document.createElement('div');gate.id='auth-gate';document.body.appendChild(gate)}
  gate.innerHTML=`<section class="auth-shell"><div class="auth-panel"><div class="auth-brand"><b>Ｓ</b><span>Saarthi</span></div><div class="auth-copy"><span class="auth-kicker">DEPARTMENT OF SOCIAL JUSTICE & EMPOWERMENT</span><h1>Secure monitoring starts with verified access.</h1><p>Use your official government employee identity to access programme monitoring and inspection workflows.</p><div class="auth-points"><span>✓ Role-based access</span><span>✓ Audit-ready activity</span><span>✓ Protected beneficiary data</span></div></div></div><div class="auth-card"><div id="auth-form"></div></div></section>`;
  authLogin();
}
const authLogin=()=>{$('#auth-form').innerHTML=`<button class="back" id="back-portal">← Back to public portal</button><span class="auth-kicker">SECURE SIGN IN</span><h2>Welcome back</h2><p class="auth-muted">Sign in with your verified government employee account.</p><form id="login-form" class="auth-form"><label>Government Employee ID or email<input name="identifier" value="GOV-2026-1001" placeholder="GOV-2026-1001 or name@gov.in" required></label><label>Password<input name="password" type="password" value="Saarthi@2026" placeholder="Enter your password" required></label><button class="auth-primary">Sign in as default officer</button></form><p class="auth-switch">New government employee? <button id="go-signup">Create verified account</button></p><div class="demo-note"><b>Default government account</b><br><b>Employee ID:</b> GOV-2026-1001<br><b>Government email:</b> arjun.mehta@dosje.gov.in<br><b>Role:</b> PMU Inspector</div>`;$('#login-form').onsubmit=login;$('#go-signup').onclick=authSignup;$('#back-portal').onclick=()=>{$('#auth-gate').remove();showLanding()}};
const authSignup=()=>{$('#auth-form').innerHTML=`<button class="back" id="go-login">← Back to sign in</button><span class="auth-kicker">EMPLOYEE VERIFICATION</span><h2>Create secure access</h2><p class="auth-muted">Your details will be verified through your official government email.</p><form id="signup-form" class="auth-form"><label>Full name<input name="name" placeholder="Your official name" required></label><label>Government Employee ID<input name="employeeId" placeholder="GOV-2026-1002" required></label><label>Official government email<input name="email" type="email" placeholder="name@dosje.gov.in" required></label><label>Create password<input name="password" type="password" minlength="8" placeholder="Minimum 8 characters" required></label><button class="auth-primary">Send verification code</button></form>`;$('#go-login').onclick=authLogin;$('#signup-form').onsubmit=signup};
const localAccounts=()=>JSON.parse(localStorage.getItem('saarthiLocalAccounts')||'[]');
async function login(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify(data)}),x=await r.json();if(r.status===404){const accounts=[{name:'Arjun Mehta',email:'arjun.mehta@dosje.gov.in',employeeId:'GOV-2026-1001',password:'Saarthi@2026',role:'PMU Inspector'},...localAccounts()];const user=accounts.find(a=>(a.email.toLowerCase()===data.identifier.toLowerCase()||a.employeeId===data.identifier.toUpperCase())&&a.password===data.password);return user?completeLogin({token:'local-'+crypto.randomUUID(),user:{name:user.name,employeeId:user.employeeId,role:user.role}}):authError('Employee ID/email or password is incorrect.')}if(!r.ok)return authError(x.error);completeLogin(x)}
async function signup(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.employeeId=data.employeeId.trim().toUpperCase().replace(/[ _]+/g,'-');if(!/^GOV-\d{4}-\d{4,}$/.test(data.employeeId))return authError('Use a valid Government Employee ID (for example GOV-2026-1001).');if(!/^[^@]+@(gov\.in|nic\.in|dosje\.gov\.in)$/.test(data.email.toLowerCase()))return authError('Use your authorized government email address.');if(data.password.length<8)return authError('Password must contain at least 8 characters.');const r=await api('/api/auth/signup',{method:'POST',body:JSON.stringify(data)}),x=await r.json();if(r.status===404)return authVerify(data.email,'123456',data);if(!r.ok)return authError(x.error);authVerify(data.email,x.demoCode,data)}
const authVerify=(email,code,pending)=>{$('#auth-form').innerHTML=`<button class="back" id="go-signup">← Edit details</button><span class="auth-kicker">EMAIL VERIFICATION</span><h2>Enter your verification code</h2><p class="auth-muted">A six-digit code was sent to <b>${esc(email)}</b>.</p><form id="verify-form" class="auth-form"><label>Verification code<input name="code" inputmode="numeric" maxlength="6" placeholder="••••••" required></label><button class="auth-primary">Verify and continue</button></form><div class="demo-note">Prototype code: <b>${code}</b>. Production uses an approved NIC/DoSJE identity service.</div>`;$('#go-signup').onclick=authSignup;$('#verify-form').onsubmit=async e=>{e.preventDefault();const entered=new FormData(e.target).get('code');const r=await api('/api/auth/verify',{method:'POST',body:JSON.stringify({email,code:entered})}),x=await r.json();if(r.status===404){if(entered!=='123456')return authError('Invalid verification code.');const user={name:pending.name,email,employeeId:pending.employeeId.toUpperCase(),password:pending.password,role:'Department Official'};const users=localAccounts().filter(a=>a.email!==email);users.push(user);localStorage.setItem('saarthiLocalAccounts',JSON.stringify(users));return completeLogin({token:'local-'+crypto.randomUUID(),user})}if(!r.ok)return authError(x.error);completeLogin(x)}};
function completeLogin(x){sessionStorage.saarthiToken=x.token;$('#auth-gate').remove();load();showToast(`Verified access granted — ${x.user.role}`)}
function showLanding(){
  let page=document.querySelector('#public-portal');if(!page){page=document.createElement('div');page.id='public-portal';document.body.appendChild(page)}
  page.innerHTML=`<header class="portal-header"><div class="portal-brand"><span class="emblem">☸</span><div><b>सामाजिक न्याय और अधिकारिता विभाग</b><small>Department of Social Justice & Empowerment · Government of India</small></div></div><nav><a href="#about">About</a><a href="#monitoring">Monitoring</a><a href="#grievance">Grievances</a><button id="portal-login" class="portal-login">Official Login</button><button id="portal-signup" class="portal-signup">Official Sign Up</button></nav></header><main class="portal-main"><section class="portal-hero"><div><span class="flag-label">SMART GOVERNANCE PLATFORM</span><h1>Transparent monitoring.<br><i>Better public service.</i></h1><p>Real-time oversight of DoSJE-supported institutes, projects and NGOs—built for accountability and beneficiary welfare.</p><div class="hero-actions"><button id="hero-login" class="portal-login">Official Login →</button><a href="#grievance" class="portal-outline">Share feedback</a></div></div><div class="hero-orbit"><span>☸</span><b>SAARTHI</b><small>Secure · Accountable · Accessible</small></div></section><section id="monitoring" class="portal-stats"><article><b>128</b><span>Projects monitored</span></article><article><b>116</b><span>Live CCTV feeds</span></article><article><b>87%</b><span>Average compliance</span></article><article><b>24×7</b><span>Monitoring support</span></article></section><section id="about" class="portal-info"><div><span class="flag-label">ONE CONNECTED SYSTEM</span><h2>Monitoring that puts people first.</h2><p>Officials can monitor project compliance, conduct inspections, and act on alerts. Beneficiaries can directly share their experience or concern with the Department.</p></div><div class="info-cards"><article><span>◉</span><b>Live monitoring</b><p>Authorized CCTV, attendance and operational-status oversight.</p></article><article><span>✓</span><b>Fair inspections</b><p>Risk-based, transparent inspection assignments.</p></article><article><span>◎</span><b>Direct grievance access</b><p>Raise issues without depending on the NGO.</p></article></div></section><section id="grievance" class="grievance"><div class="grievance-copy"><span class="flag-label">BENEFICIARY FEEDBACK & GRIEVANCE</span><h2>Your voice matters.</h2><p>Share feedback or a concern about an NGO, project, institute, service, or staff member. Your grievance goes directly to the Department for review.</p><ul><li>You may submit anonymously.</li><li>You will receive a grievance reference number.</li><li>Urgent concerns may trigger a review or surprise inspection.</li></ul></div><form id="feedback-form" class="feedback-form"><h3>Submit feedback</h3><label>Project / NGO / Institute (optional)<input name="ngo" placeholder="Name of project or organisation"></label><label>Type of grievance<select name="category" required><option value="">Select a category</option><option>Service not provided</option><option>Staff misconduct</option><option>Fake attendance / reporting</option><option>Discrimination or harassment</option><option>Other concern</option></select></label><label>Tell us what happened<textarea name="message" placeholder="Write your feedback or grievance here…" required></textarea></label><label class="anonymous"><input type="checkbox" name="anonymous"> Submit anonymously</label><button class="portal-submit">Submit grievance securely</button><p id="feedback-result" class="feedback-result"></p></form></section></main><footer class="portal-footer"><div><b>Saarthi</b> · Smart Real-Time Monitoring & Inspection</div><span>© Department of Social Justice & Empowerment, Government of India</span></footer>`;
  $('#portal-login').onclick=$('#hero-login').onclick=showAuth;$('#portal-signup').onclick=()=>{showAuth();authSignup()};const feedbackForm=$('#feedback-form');feedbackForm.querySelector('label').insertAdjacentHTML('afterend',`<label>Beneficiary mobile number <span class="required">*</span><input name="phone" inputmode="numeric" maxlength="10" pattern="[0-9]{10}" placeholder="10-digit mobile number" required><small class="contact-note">Used only by DoSJE to verify and follow up. It is never shown to the NGO.</small></label>`);feedbackForm.querySelector('.anonymous').innerHTML=`<input type="checkbox" name="anonymous"> Keep my identity hidden from the NGO <small>(DoSJE can still verify this grievance privately.)</small>`;feedbackForm.onsubmit=submitFeedback;
}
async function submitFeedback(e){e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));data.phone=String(data.phone||'').replace(/\D/g,'');const result=$('#feedback-result');if(!/^\d{10}$/.test(data.phone)){result.textContent='Enter a valid 10-digit beneficiary mobile number.';result.className='feedback-result error';return}data.anonymous=Boolean(data.anonymous);const r=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(r.status===404){const ref='GRV-'+Math.floor(100000+Math.random()*899999);result.textContent=`Grievance submitted. Your reference number is ${ref}.`;result.className='feedback-result success';form.reset();return}const x=await r.json();if(!r.ok){result.textContent=x.error;result.className='feedback-result error';return}result.textContent=`Grievance submitted successfully. Your reference number is ${x.reference}.`;result.className='feedback-result success';form.reset()}
function authError(message){const form=$('#auth-form');let error=form.querySelector('.auth-error');if(!error){error=document.createElement('div');error.className='auth-error';form.prepend(error)}error.textContent=message}
const authStyle=document.createElement('style');authStyle.textContent=`#auth-gate{position:fixed;inset:0;z-index:30;background:#eff5f1;font-family:DM Sans,sans-serif}.auth-shell{min-height:100%;display:grid;grid-template-columns:1.1fr .9fr}.auth-panel{background:linear-gradient(145deg,#093b2f,#175a45);color:#fff;padding:58px clamp(35px,8vw,130px);display:flex;flex-direction:column}.auth-brand{font:800 27px Manrope;display:flex;gap:10px;align-items:center}.auth-brand b{color:#0b3d30;background:#d5f36a;padding:5px 8px;border-radius:9px;font-size:16px}.auth-copy{margin:auto 0}.auth-kicker{font:700 10px DM Sans;letter-spacing:1.3px;color:#7cb9a2}.auth-copy h1{font:800 clamp(32px,4vw,54px) Manrope;line-height:1.12;max-width:550px;margin:18px 0}.auth-copy p{font-size:16px;line-height:1.7;color:#c5dbd1;max-width:490px}.auth-points{display:grid;gap:13px;margin-top:36px;color:#e7f5ec;font-size:13px}.auth-card{display:grid;place-items:center;padding:40px}.auth-card>div{width:min(390px,100%)}.auth-card h2{font:800 29px Manrope;margin:10px 0 5px}.auth-muted{color:#6b7774;line-height:1.55;margin:0 0 25px}.auth-form{display:grid;gap:15px}.auth-form label{font-size:12px;font-weight:700;color:#344640;display:grid;gap:7px}.auth-form input{padding:12px;border:1px solid #dbe5e0;border-radius:8px;font:14px DM Sans}.auth-primary{border:0;background:#167d59;color:#fff;padding:13px;border-radius:8px;font:700 14px DM Sans;cursor:pointer;margin-top:4px}.auth-switch{text-align:center;color:#6b7774;font-size:13px;margin-top:22px}.auth-switch button,.back{border:0;background:transparent;color:#167d59;font-weight:700;cursor:pointer}.back{padding:0;margin-bottom:20px}.demo-note{margin-top:22px;background:#f0f7f3;border-radius:8px;padding:11px;color:#557068;font-size:11px;line-height:1.55}.auth-error{background:#ffebe9;color:#b8312f;padding:9px;border-radius:7px;font-size:12px;margin-bottom:12px}@media(max-width:760px){.auth-shell{grid-template-columns:1fr}.auth-panel{min-height:260px;padding:30px}.auth-copy{margin-top:45px}.auth-copy h1{font-size:30px}.auth-copy p,.auth-points{display:none}.auth-card{padding:34px 25px}}`;document.head.appendChild(authStyle);
$('#date').textContent=new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'});const mobileCctvParams=new URLSearchParams(location.search);if(mobileCctvParams.get('mobileCctv'))showMobileCctvPhone(mobileCctvParams.get('mobileCctv'),mobileCctvParams.get('slot'));else if(sessionStorage.saarthiToken)load();else showLanding();
